w=openpyxl.load_workbook(R/'overrides/reports/community-communication-plan-2026.xlsx',data_only=True);s=w.active
labels=['م','النشاط','المسؤول','الشركاء','التاريخ','العدد','الربع الأول','الربع الثاني','الربع الثالث','الربع الرابع','الموازنة','نوع الفعالية','دور دائرة التواصل والإعلام']
