for row in s.iter_rows(min_row=6):
 if row[2].value is not None: rows.append({'row':row[0].row,'values':[c.value if isinstance(c.value,(int,float,str)) or c.value is None else str(c.value) for c in row[1:14]]})
data={'sheet':s.title,'heading':s['B2'].value,'labels':labels,'rows':rows,'merged':[str(x) for x in s.merged_cells.ranges]}
